      riga.append(nodo4(doc, "strong", "", linea?.question || linea?.domanda || "linea senza domanda"));
      const previsto = frasiSpesa(linea?.estimate);
      if (previsto) riga.append(nodo4(doc, "span", "", `previsti ${previsto}`));
