// src/bridge/legacy-dom.js
var VISTA_PER_SCHERMATA = Object.freeze({
  chat: "schermoChat",
  vuota: "schermoVuota",
  terminal: "schermoTerminale",
  browser: "schermoBrowser",
  // 06/9 B8: senza questa riga setView('browser') non trovava la vista e la scheda «Browser» non faceva niente
  diff: "schermoReview",
  capability: "schermoCapability",
  dashboard: "schermoBoard",
  memoria: "schermoMemoria",
  attivita: "schermoAttivita",
  note: "schermoNote",
  // 06/9 C24: senza questa riga #schermoNote non riceveva `data-view` e setView('note') usciva subito
  progetti: "schermoProgetti",
  // 06/9: la stessa riga che era mancata alle Note — trovato dal cancello, non ripetuto
  settings: "schermoImpostazioni",
  doctor: "schermoDoctor",
  libreria: "schermoLibreria",
  ricerca: "schermoRicerca",
  officina: "schermoOfficina",
  automations: "schermoAutomazioni"
});
var VISTA_PER_VAIA = Object.freeze({
  chat: "chat",
  vuota: "vuota",
  terminale: "terminal",
  review: "diff",
  browser: "browser",
  capability: "capability",
  // 06/9 B8 (taccuino tema chiaro): la scheda «Browser» aveva data-mode="undefined" e portava alla Board
  board: "dashboard",
  memoria: "memoria",
  attivita: "attivita",
  note: "note",
  progetti: "progetti",
  impostazioni: "settings",
  doctor: "doctor",
  libreria: "libreria",
  ricerca: "ricerca",
  officina: "officina",
  automazioni: "automations"
});
function uno(root, selettore) {
  const el25 = root.querySelector(selettore);
  if (!el25) throw new Error(`ponte: manca nel mockup «${selettore}»`);
  return el25;
}
function battezza(el25, { id, classi = [], dati = {} }) {
  if (id) el25.id = id;
  for (const c of classi) el25.classList.add(c);
  for (const [k, v] of Object.entries(dati)) el25.setAttribute(`data-${k}`, v);
  return el25;
}
function montaPonteLegacy(documentObj = document) {
  const radice2 = documentObj.querySelector(".talos-shell");
  if (!radice2) throw new Error("ponte: la pagina non ha il guscio del mockup (.talos-shell)");
  if (documentObj.getElementById("talos-legacy")) return;
  const [frammentiNascosti, frammentiVisibili] = frammenti_default.split("<!-- STRATO VISIBILE -->");
  const legacy = documentObj.createElement("div");
  legacy.id = "talos-legacy";
  legacy.hidden = true;
  legacy.innerHTML = frammentiNascosti;
  documentObj.body.append(legacy);
  const strato = documentObj.createElement("div");
  strato.id = "talos-legacy-strato";
  strato.innerHTML = frammentiVisibili || "";
  documentObj.body.append(strato);
  battezza(radice2, { id: "app", classi: ["app-shell"] });
  documentObj.documentElement.setAttribute("data-vista", "sessione");
  documentObj.documentElement.setAttribute("data-schermo", "chat");
  const sidebar = uno(radice2, ".talos-sidebar");
  battezza(sidebar, { id: "sessionsPanel", classi: ["sessions-panel"] });
  battezza(uno(sidebar, ".talos-brand .talos-icon-button"), { id: "notificationsBtn" });
  battezza(uno(sidebar, '.talos-brand [data-azione="barra"]'), { id: "sessionsCollapseBtn" });
  battezza(uno(sidebar, ".talos-sidebar__actions .talos-field__input"), { id: "sessionSearch" });
  battezza(uno(sidebar, "#voceNuova"), { id: "newSessionBtn" });
  const sessioni = uno(sidebar, ".talos-sidebar__sessions");
  battezza(sessioni, { id: "sessionList", classi: ["session-list"] });
  for (const finta of sessioni.querySelectorAll(".talos-session-item")) finta.remove();
  const fissate = uno(sidebar, '[data-c="NavGroup"]:has(.talos-eyebrow[data-t="fissate"])');
  for (const finta of fissate.querySelectorAll(".talos-session-item")) finta.remove();
  fissate.dataset.fissate = "vuoto";
  fissate.hidden = true;
  battezza(uno(sidebar, ".talos-resizer--sidebar"), { classi: ["panel-resize-handle"], dati: { resize: "sessions" } });
  for (const [vista, id] of Object.entries(VISTA_PER_SCHERMATA)) {
    const schermata = uno(radice2, `#${id}`);
    battezza(schermata, { classi: ["view-pane"], dati: { view: vista } });
    if (!schermata.hidden) schermata.classList.add("active");
  }
  for (const tab of radice2.querySelectorAll('[data-vistetab] [role="tab"][data-vaia]')) {
    battezza(tab, { classi: ["mode-tab"], dati: { mode: VISTA_PER_VAIA[tab.dataset.vaia] === "diff" ? "diff" : VISTA_PER_VAIA[tab.dataset.vaia] } });
  }
  const chat = uno(radice2, "#schermoChat");
  battezza(chat, { classi: ["chat-view"] });
  battezza(uno(chat, ".talos-conversation"), { classi: ["conversation"] });
  battezza(uno(chat, ".talos-conversation__column"), { id: "conversation" });
  for (const turno of chat.querySelectorAll(".talos-conversation__column > .talos-turn")) turno.remove();
  const piede = uno(chat, ".talos-chat-foot");
  battezza(uno(piede, ".talos-status-strip"), { classi: ["run-strip"] });
  const coda = uno(piede, ".talos-queue");
  battezza(coda, { id: "queuedMessage", classi: ["queued-message"] });
  battezza(uno(coda, ".talos-queue__text"), { id: "queuedMessageText" });
  battezza(uno(coda, ".talos-button"), { id: "cancelQueued" });
  coda.hidden = true;
  const compositore = uno(piede, "#composerForm");
  battezza(uno(compositore, ".talos-send"), { classi: ["send-btn"] });
  battezza(uno(compositore, ".talos-composer__mic"), { classi: ["composer-mic"] });
  battezza(uno(piede, ".talos-statusbar"), { classi: ["runtime-status"] });
  for (const demo of documentObj.querySelectorAll("#regioneToast .talos-toast")) {
    demo.hidden = true;
    demo.dataset.demo = "1";
  }
  battezza(uno(chat, ".talos-topbar__title h1"), { id: "sessionTitle" });
  const titolo2 = uno(chat, ".talos-topbar__title");
  battezza(titolo2, { id: "sessionTitleButton", dati: { "open-sheet": "sessionTree" } });
  titolo2.setAttribute("role", "button");
  titolo2.tabIndex = 0;
  const albero = uno(chat, '.talos-topbar__actions [data-apre-velo="veloAlbero"]');
  albero.removeAttribute("data-apre-velo");
  battezza(albero, { dati: { "open-sheet": "sessionTree" } });
  battezza(uno(chat, '.talos-topbar__actions [data-azione="comandi"]'), { id: "commandPaletteBtn" });
  battezza(uno(chat, '.talos-topbar__actions [data-azione="comprimi"]'), { id: "compactSessionBtn" });
  battezza(uno(chat, '.talos-topbar__actions [data-azione="dettagli"]'), { classi: ["desktop-context-toggle"], dati: { "open-panel": "inspector" } });
  battezza(uno(chat, '.talos-topbar__actions .talos-icon-button[title="Riprendi"]'), { id: "resumeSessionBtn" });
  battezza(uno(chat, ".talos-topbar"), { classi: ["topbar"] });
  battezza(uno(chat, ".talos-topbar__actions"), { classi: ["topbar-right"] });
  const terminale = uno(radice2, "#schermoTerminale");
  const corpoTerminale = uno(terminale, ".talos-terminal__body");
  battezza(corpoTerminale, { id: "realTerminalMount", classi: ["terminal-window"] });
  if (corpoTerminale) corpoTerminale.replaceChildren();
  battezza(uno(terminale, ".talos-terminal__foot"), { id: "terminalStatusChip" });
  const inspector = uno(radice2, ".talos-inspector");
  battezza(inspector, { id: "inspectorPanel", classi: ["inspector-panel"] });
  battezza(uno(inspector, ".talos-resizer--inspector"), { classi: ["panel-resize-handle"], dati: { resize: "inspector" } });
  battezza(uno(inspector, "#railTabs"), { classi: ["inspector-tabs"] });
  const schede = { contesto: "context", file: "files", agenti: "agents", processi: "processes" };
  for (const [rail, nome] of Object.entries(schede)) {
    const tab = uno(inspector, `[data-rail="${rail}"]`);
    battezza(tab, { id: `inspector-tab-${nome}`, dati: { "inspector-tab": nome } });
    if (tab.getAttribute("aria-selected") === "true") tab.classList.add("active");
    const pannello = uno(inspector, `#${tab.getAttribute("aria-controls")}`);
    battezza(pannello, { classi: ["inspector-section"], dati: { "inspector-section": nome } });
    if (!pannello.hidden) pannello.classList.add("active");
  }
  const legacyFiles = legacy.querySelector("#inspector-files");
  if (legacyFiles) battezza(uno(inspector, "#railFile"), { id: "railFile" });
  if (legacyFiles) {
    legacyFiles.dataset.legacyId = legacyFiles.id;
    legacyFiles.removeAttribute("id");
  }
  for (const nodo11 of legacy.querySelectorAll('[id^="fileTree"]')) {
    nodo11.dataset.legacyId = nodo11.id;
    nodo11.removeAttribute("id");
  }
  const alberoCartella = inspector.querySelector("#alberoCartella");
  if (alberoCartella) {
    alberoCartella.id = "inspector-files";
    for (const b of inspector.querySelectorAll('[aria-controls="alberoCartella"]')) b.setAttribute("aria-controls", "inspector-files");
  }
  const alberoFile = inspector.querySelector("#alberoFile");
  if (alberoFile) {
    alberoFile.classList.add("file-tree");
    alberoFile.replaceChildren();
  }
  for (const demo of inspector.querySelectorAll('#railProcessi [data-c="ProcessRow"]')) demo.remove();
  const veloAlbero = documentObj.querySelector("#veloAlbero");
  if (veloAlbero) {
    const titolo3 = veloAlbero.querySelector(".talos-dialog__title");
    if (titolo3) titolo3.textContent = "I rami di questa sessione";
    const albero2 = veloAlbero.querySelector('[data-c="BranchTree"]');
    if (albero2) {
      albero2.replaceChildren();
      const p = documentObj.createElement("p");
      p.className = "talos-inspector__hint";
      p.textContent = "Nessun ramo ancora. Quando modificherai un tuo messaggio, la sessione si dividerà qui: il ramo vecchio resta leggibile e riapribile.";
      albero2.appendChild(p);
    }
    for (const b of veloAlbero.querySelectorAll(".talos-dialog__footer .talos-button--secondary, .talos-dialog__body .talos-card")) b.hidden = true;
  }
  return legacy;
}

// src/main.js
montaPonteLegacy(document);
await Promise.resolve().then(() => (init_app(), app_exports));
var { initTalosDesktopBackground: initTalosDesktopBackground2 } = await Promise.resolve().then(() => (init_desktop_background(), desktop_background_exports));
initTalosDesktopBackground2();
var { montaAnimazioniMockup: montaAnimazioniMockup2 } = await Promise.resolve().then(() => (init_animazioni_mockup(), animazioni_mockup_exports));
montaAnimazioniMockup2(document);
